/* eslint-disable @typescript-eslint/no-explicit-any */
import { Component, ViewChild, OnInit } from '@angular/core';
import { MatTableDataSource } from '@angular/material/table';
import { co } from '@fullcalendar/core/internal-common';
import {
  ApexAxisChartSeries,
  ApexChart,
  ChartComponent,
  ApexDataLabels,
  ApexPlotOptions,
  ApexYAxis,
  ApexXAxis,
  ApexResponsive,
  ApexLegend,
  ApexFill,
} from 'ng-apexcharts';
import { apiResultFormat } from 'src/app/core/core.index';
import { routes } from 'src/app/core/helpers/routes';
import { CommonService } from 'src/app/core/service/common/common.service';
import { DataService } from 'src/app/core/service/data/data.service';
import { SettingsService } from 'src/app/core/service/settings/settings.service';
import { expiredproduct,tickets,DonationProduct } from 'src/app/shared/model/page.model';
import {
  PaginationService,
} from 'src/app/shared/shared.index';
import { Router } from '@angular/router';

import Swal from 'sweetalert2';
export type ChartOptions = {
  series: ApexAxisChartSeries | any;

  chart: ApexChart | any;

  responsive: ApexResponsive | any;

  colors: any;

  dataLabels: ApexDataLabels | any;

  plotOptions: ApexPlotOptions | any;

  yaxis: ApexYAxis | any;

  xaxis: ApexXAxis | any;

  legend: ApexLegend | any;

  fill: ApexFill | any;
};

@Component({
  selector: 'app-admin-dashboard',
  templateUrl: './admin-dashboard.component.html',
  styleUrl: './admin-dashboard.component.scss',
})
export class AdminDashboardComponent {
  initChecked = false;
  public routes = routes;
  public currency!: string;
  @ViewChild('chart') chart!: ChartComponent;
  public chartOptions: Partial<ChartOptions>;
  public selectedYear: string = '';

  constructor(
    private common: CommonService,
    private data: DataService,
    private pagination: PaginationService,
    private router: Router
  ) {
    const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    this.chartOptions = {
      series: [
        {
          name: 'Complete',
          data: new Array(12).fill(0),
        },
        {
          name: 'Pending',
          data: new Array(12).fill(0),
        },
      ],
      colors: ['#28C76F', '#EA5455'],
      chart: {
        type: 'bar',
        height: 320,
        stacked: true,
        toolbar: {
          show: true,
        },
        zoom: {
          enabled: true,
        },
      },
      responsive: [
        {
          breakpoint: 280,
          options: {
            legend: {
              position: 'bottom',
              offsetY: 0,
            },
          },
        },
      ],
      plotOptions: {
        bar: {
          horizontal: false,
          borderRadius: 4,
          borderRadiusApplication: 'end',
          borderRadiusWhenStacked: 'all',
          columnWidth: '20%',
        },
      },
      dataLabels: {
        enabled: false,
      },
      yaxis: {
        min: 0,
        tickAmount: 5,
        labels: {
          formatter: (val: number) => {
            return val.toFixed(0);
          },
        },
      },
      xaxis: {
        categories: months,
        labels: {
          style: {
            colors: '#333',
            fontSize: '12px',
          },
        },
      },
      legend: {
        show: true,
        position: 'top',
        horizontalAlign: 'right',
        fontSize: '14px',
        markers: {
          width: 10,
          height: 10,
        },
      },
      fill: {
        opacity: 1,
      },
    };

    this.common.currency$.subscribe((res: string) => {
      this.currency = res;
    });

    this.getDashboardData();
    this.getHelpDeskTickets();
    this.getGraphData();
  }


  // pagination variables
  public tableData: Array<expiredproduct> = [];
  public pageSize = 10;
  public serialNumberArray: Array<number> = [];
  public totalData = 0;
  showFilter = false;
  dataSource!: MatTableDataSource<expiredproduct>;
  public searchDataValue = '';
  //** / pagination variables
  public DonationCount = 0;
  public UsersCount = 0;
  public WareHouseCount = 0;
  public HelpDeskCount = 0;
  public PlatformAdminCount = 0;
  public WarehouseAdminCount = 0;
  public StaffAdminCount = 0;
  public CategoryCount = 0;
  public SubCategoryCount = 0;
  public ReferralCount = 0;
  public ticketsData: Array<tickets> = [];
  public donationData: Array<DonationProduct> = [];
  public years: Array<string> = [];

  confirmColor() {
    const swalWithBootstrapButtons = Swal.mixin({
      customClass: {
        confirmButton: ' btn btn-success',
        cancelButton: 'me-2 btn btn-danger',
      },
      buttonsStyling: false,
    });

    swalWithBootstrapButtons
      .fire({
        title: 'Are you sure?',
        text: "You won't be able to revert this!",
        confirmButtonText: 'Yes, delete it!',
        showCancelButton: true,
        cancelButtonText: 'Cancel',
        reverseButtons: true,
      })
      .then((result) => {
        if (result.isConfirmed) {
          swalWithBootstrapButtons.fire(
            'Deleted!',
            'Your file has been deleted.',
            'success'
          );
        } else if (result.dismiss === Swal.DismissReason.cancel) {
          swalWithBootstrapButtons.fire(
            'Cancelled',
            'Your imaginary file is safe :)',
            'error'
          );
        }
      });
  }
  selectAll(initChecked: boolean) {
    if (!initChecked) {
      this.tableData.forEach((f) => {
        f.isSelected = true;
      });
    } else {
      this.tableData.forEach((f) => {
        f.isSelected = false;
      });
    }
  }
  private getDashboardData(): void {
      this.data.getDashboardData().subscribe((apiRes: any) => {
        this.DonationCount = apiRes.results.pending_donations+apiRes.results.completed_donations
        this.UsersCount = apiRes.results.individual_users
        this.WareHouseCount = apiRes.results.total_warehouses
        this.ticketsData = apiRes.results.closed_tickets+ apiRes.results.open_tickets
        this.PlatformAdminCount= apiRes.results.platform_admins
        this.WarehouseAdminCount = apiRes.results.warehouse_admins
        this.StaffAdminCount= apiRes.results.support_staffs
        this.CategoryCount = apiRes.results.total_categories
        this.SubCategoryCount = apiRes.results.total_sub_categories
        this.ReferralCount = apiRes.results.total_refferal_count
      });
    }

  private getGraphData(): void {
    this.data.getGraphData().subscribe((apiRes: any) => {
      const stats = apiRes.results.stats;
      // Get unique years by using Set and ensure string type
      const uniqueYears: string[] = Array.from(new Set(stats.map((item: any) => item.year.toString())));
      this.years = uniqueYears;
      this.selectedYear = uniqueYears[0];
      
      // Filter stats for the selected year and update chart
      const yearStats = stats.filter((item: any) => item.year.toString() === this.selectedYear);
      this.updateChartData(yearStats);
    });
  }

  public onYearSelect(year: string): void {
    this.selectedYear = year;
    this.data.getGraphData().subscribe((apiRes: any) => {
      const stats = apiRes.results.stats;
      const yearStats = stats.filter((item: any) => item.year.toString() === year);
      this.updateChartData(yearStats);
    });
  }

  private updateChartData(yearStats: any[]): void {
    if (yearStats && yearStats.length > 0) {
      // Initialize arrays for each month
      const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
      const completeData = new Array(12).fill(0);
      const pendingData = new Array(12).fill(0);

      // Map month names to indices
      const monthIndexMap: { [key: string]: number } = {
        'January': 0, 'February': 1, 'March': 2, 'April': 3, 'May': 4, 'June': 5,
        'July': 6, 'August': 7, 'September': 8, 'October': 9, 'November': 10, 'December': 11
      };

      // Update data arrays with actual values
      yearStats.forEach(stat => {
        const monthIndex = monthIndexMap[stat.month];
        if (monthIndex !== undefined) {
          completeData[monthIndex] = stat.completed_donations || 0;
          pendingData[monthIndex] = stat.pending_donations || 0;
        }
      });

      // Update the chart options
      this.chartOptions = {
        ...this.chartOptions,
        series: [
          {
            name: 'Complete',
            data: completeData,
          },
          {
            name: 'Pending',
            data: pendingData,
          },
        ],
      };

      // Force chart update
      if (this.chart) {
        this.chart.updateOptions(this.chartOptions);
      }
    }
  }

  private getHelpDeskTickets(): void {
      this.data.getHelpDeskTickets(1,'Open','All').subscribe((apiRes: any) => {
        this.HelpDeskCount = apiRes.results.pagination.total_items
        this.ticketsData = apiRes.results.tickets
      });
    }

  navigateToChat(ticket: any): void {
    this.router.navigate(['/application/chat'], { 
      queryParams: { 
        ticketId: ticket.ticket_id,
        subject: ticket.subject,
        status: ticket.ticket_status
      }
    });
  }
}